    def findKthSmallest(self, coins: List[int], k: int) -> int:
        def count_up_to(limit):
            # Count number of distinct amounts <= limit that can be formed
            # Using inclusion-exclusion principle
            n = len(coins)
            count = 0

            # Iterate through all non-empty subsets of coins
            # For each subset, calculate the LCM of the coins in the subset
            # and count multiples of that LCM up to limit
            for mask in range(1, 1 << n):
                # Get the subset of coins
                subset = []
                for i in range(n):
                    if mask & (1 << i):
                        subset.append(coins[i])

                # Calculate LCM of all coins in subset
                lcm_val = subset[0]
                for i in range(1, len(subset)):
                    # LCM(a,b) = a * b / GCD(a,b)
                    gcd_val = self.gcd(subset[i], lcm_val)
                    lcm_val = subset[i] * lcm_val // gcd_val

                # Count multiples of lcm_val that are <= limit
                multiples = limit // lcm_val

                # If subset size is odd, add to count; if even, subtract
                # (inclusion-exclusion: odd sets add, even sets subtract)
                if len(subset) % 2 == 1:
                    count += multiples
                else:
                    count -= multiples

            return count

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        # Binary search on the answer
        left, right = 1, k * max(coins)

        while left < right:
            mid = (left + right) // 2
            if count_up_to(mid) >= k:
                right = mid
            else:
                left = mid + 1

        return left

